1	/**
2	 * Incremental sync (ISC-5, ISC-7, ISC-8, ISC-12, ISC-17).
3	 *
4	 * Daily pull-only refresh. Asks PocketSmith only for transactions changed since
5	 * the last successful run (updated_since = last sync timestamp, ISC-5), pages to
6	 * completion, and upserts base fields through the Store. The verbatim source
7	 * JSON is retained on every row (ISC-12).
8	 *
9	 * Non-destructive (ISC-17): like backfill, this refreshes base fields via the
10	 * Store's ON CONFLICT DO UPDATE and never touches transaction_overrides, so a
11	 * re-sync never destroys a user's overlay. It only ever refreshes base facts.
12	 *
13	 * Failure alerting (ISC-8): syncWithFailureTracking wraps runSync, counting
14	 * consecutive failures across runs and raising a Pulse/Telegram alert once two
15	 * in a row occur. A success resets the count.
16	 *
17	 * Pull-only (ISC-9): the only PocketSmith traffic is GET pagination. No webhook,
18	 * listener, or push path exists.
19	 */
20	
21	import type { Store } from "../platform/store.ts";
22	import type { UserId } from "../platform/auth.ts";
23	import { PocketSmithClient, type TransactionQuery } from "./client.ts";
24	import { toStoreTxs } from "./map.ts";
25	import {
26	  ALERT_AFTER_CONSECUTIVE_FAILURES,
27	  type Alerter,
28	  type FailureTracker,
29	} from "./alert.ts";
30	
31	export interface SyncOptions {
32	  readonly store: Store;
33	  readonly client: PocketSmithClient;
34	  /** Penny tenant id (the authenticated user_id every store call is scoped by). */
35	  readonly userId: UserId;
36	  /** PocketSmith user id. Resolved via GET /me when omitted. */
37	  readonly pocketsmithUserId?: number;
38	  /** Clock injection for deterministic tests; defaults to now. */
39	  readonly now?: () => Date;
40	}
41	
42	export interface SyncResult {
43	  readonly pages: number;
44	  readonly transactions: number;
45	  /** The updated_since the run sent, or null on a first run with no bookmark. */
46	  readonly updatedSince: string | null;
47	  readonly completedAt: string;
48	}
49	
50	/**
51	 * Run one incremental sync. ISC-5: updated_since equals the last successful sync
52	 * timestamp. On the very first run (no bookmark yet) it pulls everything, which
53	 * is the correct behaviour if a backfill has not seeded the bookmark.
54	 */
55	export async function runSync(opts: SyncOptions): Promise<SyncResult> {
56	  const now = opts.now ?? (() => new Date());
57	  const correlationId = crypto.randomUUID();
58	
59	  // ISC-5: the bookmark is the last successful run's timestamp.
60	  const updatedSince = await opts.store.getLastSyncAt(opts.userId);
61	
62	  const pocketsmithUserId =
63	    opts.pocketsmithUserId ?? (await resolvePocketSmithUserId(opts.client));
64	
65	  const query: TransactionQuery =
66	    updatedSince !== null ? { updatedSince } : {};
67	
68	  let pages = 0;
69	  let transactions = 0;
70	
71	  // ISC-4: drain to completion.
72	  for await (const page of opts.client.paginate(pocketsmithUserId, query)) {
73	    pages += 1;
74	    const txs = toStoreTxs(page);
75	    if (txs.length > 0) {
76	      // ISC-17: base-field refresh only; overlay untouched.
77	      await opts.store.upsertTransactions(opts.userId, txs);
78	      transactions += txs.length;
79	    }
80	  }
81	
82	  const completedAt = now().toISOString();
83	
84	  // ISC-15: append a sync event.
85	  await opts.store.appendEvent(opts.userId, {
86	    id: crypto.randomUUID(),
87	    ts: Date.parse(completedAt),
88	    actor: "sync",
89	    correlationId,
90	    kind: "ingest.sync.completed",
91	    payloadJson: JSON.stringify({ updatedSince, pages, transactions }),
92	  });
93	
94	  // Advance the bookmark only after a fully successful drain (ISC-5).
95	  await opts.store.setLastSyncAt(opts.userId, completedAt);
96	
97	  return { pages, transactions, updatedSince, completedAt };
98	}
99	
100	export interface TrackedSyncDeps {
101	  readonly failures: FailureTracker;
102	  readonly alerter: Alerter;
103	}
104	
105	export interface TrackedSyncOutcome {
106	  readonly ok: boolean;
107	  readonly result?: SyncResult;
108	  readonly error?: unknown;
109	  /** Consecutive failures after this run (0 on success). */
110	  readonly consecutiveFailures: number;
111	  /** Whether an alert was raised on this run. */
112	  readonly alerted: boolean;
113	}
114	
115	/**
116	 * Run a sync with consecutive-failure tracking and alerting (ISC-8). A success
117	 * resets the counter; two consecutive failures raise a Pulse/Telegram alert.
118	 * Never throws — the cron entry inspects the outcome and sets its exit code.
119	 */
120	export async function syncWithFailureTracking(
121	  opts: SyncOptions,
122	  deps: TrackedSyncDeps,
123	): Promise<TrackedSyncOutcome> {
124	  try {
125	    const result = await runSync(opts);
126	    await deps.failures.recordSuccess();
127	    return { ok: true, result, consecutiveFailures: 0, alerted: false };
128	  } catch (error) {
129	    const consecutiveFailures = await deps.failures.recordFailure();
130	    let alerted = false;
131	    if (consecutiveFailures >= ALERT_AFTER_CONSECUTIVE_FAILURES) {
132	      await deps.alerter.alert(
133	        `PocketSmith sync failed ${consecutiveFailures} times in a row for user ${opts.userId}. Last error: ${describeError(error)}`,
134	      );
135	      alerted = true;
136	    }
137	    return { ok: false, error, consecutiveFailures, alerted };
138	  }
139	}
140	
141	function describeError(error: unknown): string {
142	  return error instanceof Error ? error.message : String(error);
143	}
144	
145	async function resolvePocketSmithUserId(client: PocketSmithClient): Promise<number> {
146	  const me = await client.getAuthenticatedUser();
147	  if (me.id === undefined || me.id === null) {
148	    throw new Error("PocketSmith /me returned no user id");
149	  }
150	  return me.id;
151	}
