/**
 * PocketSmith transaction -> store Tx mapping.
 *
 * Money invariant (global rule): PocketSmith amounts are decimal dollars; the
 * ledger is integer cents. We convert once, here, with rounding to kill float
 * dust. Sign is preserved verbatim — PocketSmith already signs outflows
 * negative, matching the Store contract (negative = outflow).
 *
 * Raw retention (ISC-12): the verbatim PocketSmith JSON for each transaction is
 * stored as rawJson so a re-sync can diff base fields against source, and so the
 * event log can always answer "what did PocketSmith actually say".
 *
 * Envelope assignment is intentionally NOT done here. The mapper sets
 * envelopeId to null; the envelope engine resolves category -> envelope via the
 * effective-dated mappings at read time. Ingest only lands base facts.
 */

import type { Tx } from "../platform/store.ts";
import type { PocketSmithTransaction } from "./client.ts";

/** Convert decimal dollars to integer cents, rounding away float error. */
export function dollarsToCents(amount: number | undefined): number {
  if (amount === undefined || Number.isNaN(amount)) return 0;
  return Math.round(amount * 100);
}

/**
 * Map one PocketSmith transaction into a store Tx. Throws if the source row has
 * no id — an unkeyed transaction cannot be upserted idempotently.
 */
export function toStoreTx(raw: PocketSmithTransaction): Tx {
  if (raw.id === undefined || raw.id === null) {
    throw new Error("PocketSmith transaction is missing an id; cannot map");
  }
  const accountId = raw.transaction_account?.id;
  const categoryId = raw.category?.id;
  return {
    id: String(raw.id),
    date: raw.date ?? "",
    amountCents: dollarsToCents(raw.amount),
    accountId: accountId !== undefined ? String(accountId) : "",
    categoryId: categoryId !== undefined ? String(categoryId) : null,
    // Envelope resolution belongs to the envelope engine, not ingest.
    envelopeId: null,
    payee: raw.payee ?? "",
    isTransfer: raw.is_transfer === true,
    // ISC-23: pending transactions are listed but must not decrement balances.
    isPending: raw.status === "pending",
    // ISC-12: keep the source verbatim for diffing.
    rawJson: JSON.stringify(raw),
  };
}

/** Map a page of PocketSmith transactions, skipping any malformed (id-less) rows. */
export function toStoreTxs(rawPage: readonly PocketSmithTransaction[]): Tx[] {
  const out: Tx[] = [];
  for (const raw of rawPage) {
    if (raw.id === undefined || raw.id === null) continue;
    out.push(toStoreTx(raw));
  }
  return out;
}

/**
 * Authentication seam. Route handlers and business modules depend ONLY on the
 * resolved authenticated `userId` returned here — never on which implementation
 * is active. Enforces ISC-52 (local), ISC-53 (cloud magic-link).
 *
 *   Local  : Tailscale device trust + a PIN held in the SecretStore. 30-min idle session.
 *   Cloud  : passwordless email magic-link. Request link -> verify token -> mint session.
 *
 * The two implementations live in src/platform/auth/local.ts and auth/cloud.ts.
 */

export type UserId = string;

export interface Session {
  readonly userId: UserId;
  readonly issuedAt: number;
  readonly idleExpiresAt: number;
}

export interface AuthProvider {
  /**
   * Begin sign-in. Local: validate the PIN. Cloud: email a magic link.
   * Returns a session on immediate success (local PIN) or null when a
   * second step is required (cloud, link sent).
   */
  beginSignIn(input: BeginSignInInput): Promise<Session | null>;

  /**
   * Complete sign-in from a magic-link token (cloud) or refresh a PIN session.
   * Returns the session or throws on an invalid/expired token.
   */
  completeSignIn(token: string): Promise<Session>;

  /** Resolve and validate the session on an incoming request; null if unauthenticated or expired. */
  resolveSession(request: Request): Promise<Session | null>;

  /** Invalidate the active session. */
  signOut(session: Session): Promise<void>;

  /**
   * Mint the signed cookie value for a session. The server sets it as the
   * httpOnly session cookie. Both implementations encode the same stateless
   * token, so the route layer never branches on which provider is active.
   */
  mintToken(session: Session): Promise<string>;
}

export type BeginSignInInput =
  | { readonly kind: "pin"; readonly pin: string }
  | { readonly kind: "email"; readonly email: string };

/** Thrown when a magic-link or PIN attempt fails. Never leaks which user exists. */
export class AuthError extends Error {}

