27	  readonly userId: UserId;
28	  /** PocketSmith user id. Resolved via GET /me when omitted. */
29	  readonly pocketsmithUserId?: number;
30	  /** ISO date (YYYY-MM-DD) to start from. Defaults to two years ago (ISC-6). */
31	  readonly since?: string;
32	  /** Clock injection for deterministic tests; defaults to now. */
33	  readonly now?: () => Date;
34	}
