/**
 * Backfill (ISC-4, ISC-6, ISC-12, ISC-17).
 *
 * Pulls a tenant's full transaction history from a parameterised start date
 * (default two years, ISC-6) up to today, paging the PocketSmith transactions
 * endpoint to completion (ISC-4) and upserting each page through the Store.
 * Every transaction keeps its verbatim source JSON (ISC-12).
 *
 * Non-destructive (ISC-17): upserts refresh base fields only via the Store's
 * ON CONFLICT DO UPDATE; the overlay lives in transaction_overrides, which this
 * module never reads or writes. Re-running a backfill is therefore safe — base
 * facts are refreshed, user overrides are untouched.
 *
 * Pull-only (ISC-9): the only PocketSmith traffic is the GET pagination in the
 * client. No listener, webhook, or push path is involved.
 */

import type { Store } from "../platform/store.ts";
import type { UserId } from "../platform/auth.ts";
import { PocketSmithClient } from "./client.ts";
import { toStoreTxs } from "./map.ts";

export interface BackfillOptions {
  readonly store: Store;
  readonly client: PocketSmithClient;
  /** Penny tenant id (the authenticated user_id every store call is scoped by). */
  readonly userId: UserId;
  /** PocketSmith user id. Resolved via GET /me when omitted. */
  readonly pocketsmithUserId?: number;
  /** ISO date (YYYY-MM-DD) to start from. Defaults to two years ago (ISC-6). */
  readonly since?: string;
  /** Clock injection for deterministic tests; defaults to now. */
  readonly now?: () => Date;
}

export interface BackfillResult {
  readonly pages: number;
  readonly transactions: number;
  readonly since: string;
  readonly completedAt: string;
}

/** ISO date (YYYY-MM-DD) exactly `years` before `from`. */
export function isoDateYearsAgo(years: number, from: Date): string {
  const d = new Date(from.getTime());
  d.setFullYear(d.getFullYear() - years);
  return d.toISOString().slice(0, 10);
}

export async function runBackfill(opts: BackfillOptions): Promise<BackfillResult> {
  const now = opts.now ?? (() => new Date());
  const startedAt = now();
  // ISC-6: two-year default window from a parameterised start date.
  const since = opts.since ?? isoDateYearsAgo(2, startedAt);
  const correlationId = crypto.randomUUID();

  const pocketsmithUserId =
    opts.pocketsmithUserId ?? (await resolvePocketSmithUserId(opts.client));

  let pages = 0;
  let transactions = 0;

  // ISC-4: drain the generator -> every page consumed to completion.
  for await (const page of opts.client.paginate(pocketsmithUserId, { startDate: since })) {
    pages += 1;
    const txs = toStoreTxs(page);
    if (txs.length > 0) {
      // ISC-17: base-field upsert only; overlay table is never touched here.
      await opts.store.upsertTransactions(opts.userId, txs);
      transactions += txs.length;
    }
  }

  const completedAt = now().toISOString();

  // ISC-15: every state change appends an event with ts, actor, correlation id.
  await opts.store.appendEvent(opts.userId, {
    id: crypto.randomUUID(),
    ts: Date.parse(completedAt),
    actor: "sync",
    correlationId,
    kind: "ingest.backfill.completed",
    payloadJson: JSON.stringify({ since, pages, transactions }),
  });

  // A completed backfill is a successful pull; bookmark it so the first
  // incremental sync has an updated_since to work from (ISC-5).
  await opts.store.setLastSyncAt(opts.userId, completedAt);

  return { pages, transactions, since, completedAt };
}

async function resolvePocketSmithUserId(client: PocketSmithClient): Promise<number> {
  const me = await client.getAuthenticatedUser();
  if (me.id === undefined || me.id === null) {
    throw new Error("PocketSmith /me returned no user id");
  }
  return me.id;
}
